"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [475, 981, 837, 1085], \"page_id\": 5}], \"content\": \"APRIL-1950\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [62, 1060, 339, 1192], \"page_id\": 5}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [113, 1645, 1301, 1708], \"page_id\": 5}], \"content\": \"UNITED STATES TREASURY DEPARTMENT\", \"description\": null, \"id\": 5, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [795, 1706, 1293, 1765], \"page_id\": 5}], \"content\": \"OFFICE OF THE SECRETARY\", \"description\": null, \"id\": 6, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [2, 4, 1545, 2006], \"page_id\": 6}], \"content\": null, \"description\": null, \"id\": 0, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [49, 54, 188, 88], \"page_id\": 7}], \"content\": \"April 1950\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [583, 248, 902, 276], \"page_id\": 7}], \"content\": \"Table of Contents\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [1154, 375, 1212, 400], \"page_id\": 7}], \"content\": \"Page\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [266, 413, 1214, 1401], \"page_id\": 7}], \"content\": \"<table><tr><td>Treasury financing operations.</td><td>A-l</td></tr><tr><td>Summary of Federal fiscal operations</td><td>1</td></tr><tr><td>Budget receipts and expenditures</td><td>2</td></tr><tr><td>Trust accounts, etc.</td><td>8</td></tr><tr><td>Treasury cash income and outgo</td><td>12</td></tr><tr><td>General Fund of the Treasury</td><td>15</td></tr><tr><td>Debt outstanding</td><td>16</td></tr><tr><td>Statutory debt limitation</td><td>20</td></tr><tr><td>Debt operations</td><td>21</td></tr><tr><td>United States savings bonds</td><td>26</td></tr><tr><td>Treasury savings notes</td><td>30</td></tr><tr><td>Ownership of Federal securities</td><td>31</td></tr><tr><td>Treasury survey of ownership of Federal securities</td><td>33</td></tr><tr><td>Market quotations</td><td>37</td></tr><tr><td>Yields of Treasury and corporate bonds</td><td>40</td></tr><tr><td>Internal revenue collections</td><td>42</td></tr><tr><td>Monetary statistics</td><td>46</td></tr><tr><td>Capital movements</td><td>50</td></tr><tr><td>Corporations and certain other business-type activities - loans and balance sheets</td><td>66</td></tr><tr><td>Cumulative table of contents</td><td>71</td></tr></table>\", \"description\": null, \"id\": 3, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [268, 1448, 1142, 1545], \"page_id\": 7}], \"content\": \"Note: In those tables where figures have been rounded to a specified unit, all calculations (including percentages) have been made from unrounded figures. Consequently the details may not add to the totals shown.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [52, 52, 183, 81], \"page_id\": 9}], \"content\": \"April 1950\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1400, 66, 1438, 81], \"page_id\": 9}], \"content\": \"A-1\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [467, 239, 1003, 269], \"page_id\": 9}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [73, 380, 667, 404], \"page_id\": 9}], \"content\": \"April Certificate and Note Maturities\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [73, 413, 698, 689], \"page_id\": 9}], \"content\": \"On March 17, 1950, in accordance with the announcement by the Secretary of the Treasury on February 14, it was announced that subscription books would be opened on March 20 for two issues of Treasury notes. One was an issue of 1-1/4 percent Treasury notes maturing on July 1, 1951; the other was an additional amount of the 1-1/2 percent Treasury notes maturing on March 15, 1955, which were issued on March 15, 1950.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [71, 732, 691, 1141], \"page_id\": 9}], \"content\": \"The new issue of 15-month 1-1/4 percent notes, Series C-1951, was offered in exchange, par for par, for the one-year 1-1/4 percent certificates of indebtedness, Series D-1950, maturing April 1, 1950. The additional 5-year 1-1/2 percent Treasury notes, Series A-1955, were offered in exchange, at par and accrued interest, for the 18-1/2 month 1-3/8 percent Treasury notes, Series A-1950, maturing April 1, 1950. Cash subscriptions were not received. The maturing certificates, Series D-1950, amounted to $963 million and the maturing notes, Series A-1950, amounted to $7,596 million. Subscription books were closed at the close of business on March 23.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [70, 1184, 695, 1527], \"page_id\": 9}], \"content\": \"The 1-1/4 percent notes of the new issue are dated April 1, 1950, and bear interest from that date at the rate of 1-1/4 percent per annum, payable on a semiannual basis on January 1 and July 1, 1951. They will mature July 1, 1951, and are not subject to call for redemption before maturity. They were issued in bearer form only, in denominations of $1,000, $5,000, $10,000, $100,000, and $1,000,000. The notes of Series A-1955, dated March 15, 1950, form a part of the series issued pursuant to the offering circular dated February 17, 1950.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [68, 1599, 700, 1656], \"page_id\": 9}], \"content\": \"Note: Details of Treasury market financing operations are shown in the tables on \\\"Offerings\\\" and \\\"Disposition\\\", respectively, of marketable issues of bonds, notes,\", \"description\": null, \"id\": 7, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [780, 384, 1398, 436], \"page_id\": 9}], \"content\": \"are identical in all respects with those notes, with which they are freely interchangeable.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [780, 479, 1410, 691], \"page_id\": 9}], \"content\": \"Reports to the Treasury on the ownership of Government securities indicate that on January 31, 1950, about 45 percent of the maturing certificates and about 63 percent of the maturing notes were owned by reporting commercial banks and Federal Reserve Banks. The ownership figures for January 31 are the latest published for the holdings of commercial banks.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [780, 732, 1405, 886], \"page_id\": 9}], \"content\": \"Subscriptions to the new 1-1/4 percent Treasury notes amounted to $837 million, leaving $75 million to be paid in cash. Subscriptions to the 1-1/2 percent notes were made in the additional amount of $3,504 million, leaving $92 million to be paid in cash.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [775, 928, 1142, 953], \"page_id\": 9}], \"content\": \"Treasury Bills Refunded\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [780, 965, 1403, 1211], \"page_id\": 9}], \"content\": \"Treasury bills matured in March in the amount of $4.7 billion. Each of the five offerings was equal to the amount maturing. The first two were for $1,000 million each and the last three were for $900 million each. The average rates of discount, beginning with the issue dated March 2, were 1.137 percent, 1.139 percent, 1.131 percent, 1.138 percent, and 1.145 percent.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [770, 1247, 1207, 1270], \"page_id\": 9}], \"content\": \"United States Savings Bonds\", \"description\": null, \"id\": 13, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [780, 1285, 1398, 1498], \"page_id\": 9}], \"content\": \"Discontinuance of the sale of the $10 maturity value of United States savings bonds, Series E, was announced by the Treasury Department on March 15. The change was effective at the close of business on March 31, 1950. Series E bonds of $10 denomination were authorized on June 7, 1944, for issuances exclusively to members of the armed forces.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [780, 1602, 1400, 1658], \"page_id\": 9}], \"content\": \"and certificatee of indebtedness, and in the table \\\"Offer- inge of Treasury Bills\\\", in this issue of the \\\"Treasury Bulletin\\\".\", \"description\": null, \"id\": 15, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [59, 54, 212, 104], \"page_id\": 11}], \"content\": \"April 1950\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1436, 66, 1462, 106], \"page_id\": 11}], \"content\": \"1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [454, 113, 1052, 154], \"page_id\": 11}], \"content\": \"SUMMARY OF FEDERAL FISCAL OPERATIONS\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [625, 158, 848, 194], \"page_id\": 11}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [47, 187, 1462, 1676], \"page_id\": 11}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Period</th><th colspan=\\\"3\\\">Budget receipts and expenditurees 1/</th><th rowspan=\\\"2\\\">Trust accounte, etc. - net receipts or expenditures (-) 3/ b/</th><th rowspan=\\\"2\\\">Clearing account 2/</th><th rowspan=\\\"2\\\">Net increase in public debt, or decrease (-)</th><th rowspan=\\\"2\\\">Net increase in General Fund balance, or decrease (-)</th><th colspan=\\\"4\\\">Levels, end of period</th></tr><tr><th>Net receipts 2/</th><th>Expenditures 3/</th><th>Surplus, or deficit (-) 3/</th><th>General Fund ba